def gen(rng):
    def fmt(v):
        return str(len(v)) + '\n' + ' '.join(map(str, v))
    tests = [fmt([1]), fmt([5, 5]), fmt([2, 2, 2, 2, 2]), fmt([1, 2, 3, 4]), fmt([10**9, 10**9, 1, 1]),
             fmt([3, 1, 2, 1, 3, 2])]
    for n in (3, 5, 8, 10, 15, 20, 30):
        for hi in (3, 10, 1000):
            tests.append(fmt([rng.randint(1, hi) for _ in range(n)]))
    N = 100000
    tests.append(fmt([rng.randint(1, 10**9) for _ in range(N)]))
    tests.append(fmt([rng.randint(1, 50000) for _ in range(N)]))
    tests.append(fmt([7] * N))
    tests.append(fmt(list(range(1, N + 1))))
    return tests
